mapper.select:
select au.id, au.dept_id, au.login_account, au.user_name, au.school,au.major,au.country,au.agree,au.age,au.birth,au.flair,au.address,au.work_date, au.email, au.avatar, au.tel, au.sex, au.status, au.del_flag, au.login_ip, au.login_date, au.create_by, au.create_time, au.remark, ad.dept_name from ape_user au left join ape_dept ad on au.dept_id = ad.id where au.del_flag = 0
and au.user_name like concat('%',#{ew.userName},'%')
and au.major like concat('%',#{ew.major},'%')
and au.school like concat('%',#{ew.school},'%')
and au.tel like concat('%',#{ew.tel},'%')
and au.status = #{ew.status}
and au.user_type = #{ew.userType}
and au.dept_id = #{ew.deptId}

select count(*) from ape_user au left join ape_dept ad on au.dept_id = ad.id where au.del_flag = 0
and au.user_name like concat('%',#{ew.userName},'%')
and au.major like concat('%',#{ew.major},'%')
and au.school like concat('%',#{ew.school},'%')
and au.tel like concat('%',#{ew.tel},'%')
and au.status = #{ew.status}
and au.user_type = #{ew.userType}
and au.dept_id = #{ew.deptId}
